struct Particle {          // 8 floats/ints = 32 bytes
    float x, y, z;         // position
    float vx, vy, vz;      // velocity
    float mass;
    uint32_t id;
};
struct Particle ps[1000000];   // AoS: 32 MB in one array

int below_ground = 0;
for (int i = 0; i < 1000000; i++)
    if (ps[i].y < 0.0f) below_ground++;   // reads only y

